CREATE TABLE "Division" ("id" TEXT NOT NULL, "parentId" TEXT, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'district', "level" INTEGER NOT NULL DEFAULT 1, "standard" BOOLEAN NOT NULL DEFAULT true, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Division_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Division_code_key" ON "Division"("code"); CREATE INDEX "Division_parentId_idx" ON "Division"("parentId"); CREATE INDEX "Division_name_idx" ON "Division"("name");
ALTER TABLE "Division" ADD CONSTRAINT "Division_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Division"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "Organization" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "creditCode" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'institution', "divisionId" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Organization_creditCode_key" ON "Organization"("creditCode"); CREATE INDEX "Organization_divisionId_idx" ON "Organization"("divisionId"); CREATE INDEX "Organization_name_idx" ON "Organization"("name"); ALTER TABLE "Organization" ADD CONSTRAINT "Organization_divisionId_fkey" FOREIGN KEY ("divisionId") REFERENCES "Division"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "OrganizationPlaque" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrganizationPlaque_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "OrganizationPlaque_organizationId_name_key" ON "OrganizationPlaque"("organizationId", "name"); ALTER TABLE "OrganizationPlaque" ADD CONSTRAINT "OrganizationPlaque_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "DivisionMapping" ("zoneId" TEXT NOT NULL, "officialId" TEXT NOT NULL, CONSTRAINT "DivisionMapping_pkey" PRIMARY KEY ("zoneId", "officialId"));
CREATE INDEX "DivisionMapping_officialId_idx" ON "DivisionMapping"("officialId");
ALTER TABLE "DivisionMapping" ADD CONSTRAINT "DivisionMapping_zoneId_fkey" FOREIGN KEY ("zoneId") REFERENCES "Division"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DivisionMapping" ADD CONSTRAINT "DivisionMapping_officialId_fkey" FOREIGN KEY ("officialId") REFERENCES "Division"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
